package com.tecsup.pedido.model; import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.math.BigDecimal;
@Entity @Table(name="detalle_pedido") public class DetallePedido {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false)private Long idProducto;@Column(nullable=false)private Integer cantidad;@Column(nullable=false,precision=10,scale=2)private BigDecimal precio;@JsonIgnore @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="id_pedido",nullable=false)private Pedido pedido;public Long getId(){return id;}public Long getIdProducto(){return idProducto;}public void setIdProducto(Long x){idProducto=x;}public Integer getCantidad(){return cantidad;}public void setCantidad(Integer x){cantidad=x;}public BigDecimal getPrecio(){return precio;}public void setPrecio(BigDecimal x){precio=x;}public Pedido getPedido(){return pedido;}public void setPedido(Pedido x){pedido=x;}}
